// Frequency range: 40 Hz - 2 kHz
freq = hslider("Frequency [unit:Hz]", 400, 40, 2000, 1) : si.smoo;
decay = hslider("Decay Time [unit:ms]", 100, 1, 1000, 1) : si.smoo
        : *(ma.SR/1000.0) : min(1000) : max(1);
damp = hslider("Damping", 0.5, 0, 1, 0.01) : si.smoo;

// Two-point averaging low-pass filter
lowPass(x) = (x + x : *(0.5)) : *(1 - decay);

// Trigger gate
gate(x) = x > 0.5 ? 1 : 0;

// Karplus-Strong algorithm
karplusStrong(x) = x + (gate(x) : lowPass(x)) : *(0.5);

// Delay line with two feedback paths
delayLine(n) = par(i, n, _ : (gate(x) : lowPass(x)) : *(0.5));

// Main process
process = gate(karplusStrong(lowPass(x))) : delayLine(1) : delayLine(0);

